sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float amplitude;
uniform float wavelength;
uniform float speed;
half4 main(float2 coord) {
    float2 centerPx = center * size;
    float2 d = coord - centerPx;
    float dist = length(d);
    float phase = time * speed;
    float wave = sin(dist / max(wavelength, 0.0001) - phase) * amplitude;
    float2 offset = dist > 0.0 ? d / dist * wave : float2(0.0);
    half4 color = image.eval(coord + offset);
    if (color.a > 0.0) {
        color.rgb /= color.a;
    }
    color.rgb *= color.a;
    return color;
}
